    int i = 0;
    for (; i <= dim - 4; i += 4) {
        half4 vals = reinterpret_cast<const half4&>(input_row[i]);
        sum = __hadd(sum, __hadd(__hmul(vals.x, vals.x), __hmul(vals.y, vals.y)));
        sum = __hadd(sum, __hadd(__hmul(vals.z, vals.z), __hmul(vals.w, vals.w)));
    }

    // Handle remaining elements
    for (; i < dim; i++) {
        sum = __hadd(sum, __hmul(input_row[i], input_row[i]));
    }

    // Store partial sum in shared memory
    sdata[threadIdx.x] = sum;
    __syncthreads();

    // Reduction in shared memory
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            sdata[threadIdx.x] = __hadd(sdata[threadIdx.x], sdata[threadIdx.x + s]);
        }
        __syncthreads();
    }

    // Get norm for this batch element
    half norm = sdata[0];
    norm = hsqrt(norm);

    // Avoid division by zero
    if (__habs(norm) < __float2half(1e-8f)) {
        norm = __float2half(1.0f);
    }

    // Normalize the row
    half inv_norm = __hdiv(__float2half(1.0f), norm);
    half* output_row = output + batch_idx * dim;

    // Copy and normalize in chunks of 4
    i = 0;
    for (; i <= dim - 4; i += 4) {
        half4 vals = reinterpret_cast<const half4&>(input_row[i]);
        half4 result;
        result.x = __hmul(vals.x, inv_norm);
        result.y = __hmul(vals.y, inv_norm);
        result.z = __hmul(vals.z, inv_norm);
        result.w = __hmul(vals.w, inv_norm);
        reinterpret_cast<half4&>(output_row[i]) = result;
    }

    // Handle remaining elements
    for (; i < dim; i++) {
        output_row[i] = __hmul(input_row[i], inv_norm);
    }
}

